function icon(Icon, props = {}) {
  return h(Icon, {
    ...props,
    "aria-hidden": "true",
    focusable: "false",
    size: props.size || 36,
    strokeWidth: props.strokeWidth || 2.2,
  });
}

function PerkCard({ index, perk }) {
  const [ref, visible] = useRevealOnce({ delay: index * 100 });
  return h("div", { className: "perk fade-in" + (visible ? " visible" : ""), ref }, [
    h("div", { className: "perk-icon", key: "icon" }, icon(perk.icon)),
    h("div", { className: "perk-title", key: "title" }, perk.title),
    h("p", { key: "body" }, perk.body),
  ]);
}

function ContactBox({ children, delay }) {
  const [ref, visible] = useRevealOnce({ delay });
  return h("div", { className: "contact-box fade-in" + (visible ? " visible" : ""), ref }, children);
}

// Online dues are credential-gated server-side (PayPal secrets). Until the Worker says they are on, the
// block renders exactly as it always has, including the paypal.me link.
function useDuesOnline() {
  const [online, setOnline] = React.useState(false);
  React.useEffect(() => {
    const controller = new AbortController();
    fetch(`${resolveApiBase()}/membership/config`, { signal: controller.signal, headers: { Accept: "application/json" } })
      .then((response) => (response.ok ? response.json() : null))
      .then((config) => setOnline(Boolean(config && config.duesOnline === true)))
      .catch(() => {});
    return () => controller.abort();
  }, []);
  return online;
}

